-- NEW LOCAL PROPOSAL: one intentionally public concurrency-only pass and one audit record.
-- NOT secure issuance/entropy evidence. Requires exact seed approval and reconciled rehearsal.
begin;set local search_path='';set local lock_timeout='3s';set local statement_timeout='15s';
do $seed$
declare f jsonb;eid uuid;e public.events;o public.orders;audit private.audit_log;t timestamptz;approval text:=nullif(current_setting('vne.day07.approval_ref',true),'');rehearsal text:=nullif(current_setting('vne.day07.rehearsal_evidence_ref',true),'');primary_event public.events;before_outbox bigint;
begin
 if approval is null or rehearsal is null or char_length(approval)>200 or char_length(rehearsal)>200 then raise exception 'exact_seed_and_rehearsal_approval_required';end if;
 if not exists(select 1 from private.qr_admission_config where singleton and project_ref='xrocuwlofxhxoxajukne' and enabled and synthetic_admission) then raise exception 'active_exact_TEST_required';end if;
 if not exists(select 1 from pg_proc where oid=to_regprocedure('public.vne_qr_command(jsonb)') and encode(sha256(convert_to(prosrc,'UTF8')),'hex')='d8944aa95bd076f9b6180f9e26cec569c2e0fbce7f54df7c7822d6c69a13ee88') or not has_function_privilege('authenticated','public.vne_qr_command(jsonb)','execute') or has_function_privilege('anon','public.vne_qr_command(jsonb)','execute') or has_function_privilege('service_role','public.vne_qr_command(jsonb)','execute') then raise exception 'exact_scoped_wrapper_required';end if;
 if exists(select 1 from pg_roles r where r.rolname in ('anon','authenticated','service_role') and has_function_privilege(r.oid,'private.qr_command(jsonb)'::regprocedure,'execute')) then raise exception 'private_ACL_drift';end if;
 select * into primary_event from public.events where id='d0700000-0000-4000-8000-000000000001' for update;t:=primary_event.qr_release_at;
 if t is null or clock_timestamp()<primary_event.entry_opens_at or clock_timestamp()+interval '2 minutes'>=t+interval '20 minutes' then raise exception 'open_entry_with_two_minutes_remaining_required';end if;
 if (select count(*) from private.audit_log where action='day07.synthetic_enable' and object_id=primary_event.id and result='ok' and nullif(details->>'approvalRef','') is not null and (details->>'windowStart')::timestamptz=t and (details->>'windowEnd')::timestamptz=t+interval '20 minutes')<>1 then raise exception 'one_enable_audit_required';end if;
 if (select count(*) from private.member_admission where user_id in('15cbc7a4-92f6-48d8-abb2-ed68f7612271'::uuid,'1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid,'ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and state='admitted' and source='day07.synthetic-20261008' and invite_id is null)<>3 then raise exception 'exact_three_admissions_required';end if;
 if (select count(distinct s.user_id) from auth.sessions s join auth.mfa_factors f on f.id=s.factor_id and f.user_id=s.user_id where s.user_id in('1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid,'ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and s.aal='aal2' and (s.not_after is null or s.not_after>clock_timestamp()) and f.status='verified' and f.factor_type='totp')<>2 then raise exception 'two_live_MFA_sessions_required';end if;
 for f in select value from jsonb_array_elements('[{"event":"d0700000-0000-4000-8000-000000000001","tier":"d0700000-0000-4000-8000-000000000002","application":"d0700000-0000-4000-8000-000000000003","reservation":"d0700000-0000-4000-8000-000000000004","order":"d0700000-0000-4000-8000-000000000005","participation":"d0700000-0000-4000-8000-000000000006","idempotency":"d0700000-0000-4000-8000-000000000007","scannerA":"d0700000-0000-4000-8000-000000000008","scannerB":"d0700000-0000-4000-8000-000000000009","scenario":"primary-race","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":5,"closesMinutes":20},{"event":"d0710000-0000-4000-8000-000000000001","tier":"d0710000-0000-4000-8000-000000000002","application":"d0710000-0000-4000-8000-000000000003","reservation":"d0710000-0000-4000-8000-000000000004","order":"d0710000-0000-4000-8000-000000000005","participation":"d0710000-0000-4000-8000-000000000006","idempotency":"d0710000-0000-4000-8000-000000000007","scannerA":"d0710000-0000-4000-8000-000000000008","scannerB":"d0710000-0000-4000-8000-000000000009","scenario":"rotation-revoke","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":5,"closesMinutes":20},{"event":"d0720000-0000-4000-8000-000000000001","tier":"d0720000-0000-4000-8000-000000000002","application":"d0720000-0000-4000-8000-000000000003","reservation":"d0720000-0000-4000-8000-000000000004","order":"d0720000-0000-4000-8000-000000000005","participation":"d0720000-0000-4000-8000-000000000006","idempotency":"d0720000-0000-4000-8000-000000000007","scannerA":"d0720000-0000-4000-8000-000000000008","scannerB":"d0720000-0000-4000-8000-000000000009","scenario":"future-boundaries","qrMinutes":4,"entryMinutes":6,"addressMinutes":7,"startsMinutes":8,"closesMinutes":20},{"event":"d0730000-0000-4000-8000-000000000001","tier":"d0730000-0000-4000-8000-000000000002","application":"d0730000-0000-4000-8000-000000000003","reservation":"d0730000-0000-4000-8000-000000000004","order":"d0730000-0000-4000-8000-000000000005","participation":"d0730000-0000-4000-8000-000000000006","idempotency":"d0730000-0000-4000-8000-000000000007","scannerA":"d0730000-0000-4000-8000-000000000008","scannerB":"d0730000-0000-4000-8000-000000000009","scenario":"short-expiry","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":3,"closesMinutes":8}]'::jsonb) loop
  eid:=(f->>'event')::uuid;
  select * into e from public.events where id=eid for update;
  if e.id is null or e.slug is distinct from 'day07-'||(f->>'scenario') or e.status<>'published' or e.cancelled_at is not null or not e.is_synthetic or e.sales_open or e.capacity is distinct from 4 or e.timezone is distinct from 'Europe/Moscow' or e.qr_release_at is distinct from t+(f->>'qrMinutes')::integer*interval '1 minute' or e.entry_opens_at is distinct from t+(f->>'entryMinutes')::integer*interval '1 minute' or e.address_reveal_at is distinct from t+(f->>'addressMinutes')::integer*interval '1 minute' or e.starts_at is distinct from t+(f->>'startsMinutes')::integer*interval '1 minute' or e.entry_closes_at is distinct from t+(f->>'closesMinutes')::integer*interval '1 minute' then raise exception 'exact_event_fixture_required';end if;
  select * into o from public.orders where id=(f->>'order')::uuid for update;
  if o.id is null or o.reservation_id is distinct from (f->>'reservation')::uuid or o.user_id is distinct from '15cbc7a4-92f6-48d8-abb2-ed68f7612271'::uuid or o.event_id is distinct from eid or o.tier_id is distinct from (f->>'tier')::uuid or o.tier_name is distinct from 'SYNTHETIC SIMULATOR' or o.amount_minor is distinct from 1000 or o.currency is distinct from 'RUB' or o.environment is distinct from 'sandbox' or o.status<>'paid' or o.review_reason is distinct from 'Synthetic state fixture only; no payment provider called.' then raise exception 'exact_paid_sandbox_snapshot_required';end if;
  if not exists(select 1 from public.event_tiers where id=o.tier_id and event_id=eid and name='SYNTHETIC SIMULATOR' and amount_minor=1000 and currency='RUB') then raise exception 'exact_tier_required';end if;
  if not exists(select 1 from public.reservations where id=o.reservation_id and event_id=eid and tier_id=o.tier_id and user_id=o.user_id and application_id=(f->>'application')::uuid and idempotency_key=(f->>'idempotency')::uuid and status='converted' and expires_at=e.entry_closes_at) then raise exception 'exact_reservation_required';end if;
  if not exists(select 1 from public.applications where id=(f->>'application')::uuid and event_id=eid and user_id=o.user_id and status='approved') then raise exception 'approved_application_required';end if;
  perform 1 from public.participations where id=(f->>'participation')::uuid and event_id=eid and order_id=o.id and user_id=o.user_id and status='active' for update;
  if not found then raise exception 'active_participation_required';end if;
  if (select count(*) from public.staff_assignments where (id=(f->>'scannerA')::uuid and user_id='1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid or id=(f->>'scannerB')::uuid and user_id='ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and role='scanner' and event_id=eid and valid_from=t and valid_until=t+interval '20 minutes' and revoked_at is null)<>2 then raise exception 'exact_event_scanner_roles_required';end if;
  if not exists(select 1 from private.event_private_details where event_id=eid and venue_address='Вымышленная площадка DAY07 TEST, не настоящий адрес') then raise exception 'synthetic_private_address_required';end if;
  if exists(select 1 from private.ticket_passes where event_id=eid) or exists(select 1 from private.ticket_checkins where event_id=eid) or exists(select 1 from private.qr_command_receipts where event_id=eid) then raise exception 'fresh_fixture_required';end if;
  if exists(select 1 from public.payments where order_id=o.id) or exists(select 1 from public.refunds where order_id=o.id) then raise exception 'provider_records_out_of_scope';end if;
  if (select count(*) from private.audit_log where action='day07.synthetic_fixture' and object_id=eid)<>1 then raise exception 'one_fixture_source_audit_required';end if;
  select * into audit from private.audit_log where action='day07.synthetic_fixture' and object_id=eid;
  if audit.actor is not null or audit.result is distinct from 'ok' or nullif(audit.details->>'approvalRef','') is null or (audit.details->>'windowStart')::timestamptz is distinct from t or (audit.details->>'windowEnd')::timestamptz is distinct from t+interval '20 minutes' or not coalesce(audit.details @> jsonb_build_object('synthetic',true,'paymentVerified',false,'externalDelivery',false,'sourceMarker','day07.synthetic-20261008','scenario',f->>'scenario','memberId','15cbc7a4-92f6-48d8-abb2-ed68f7612271','scannerAId','1e7259c2-ad13-43a1-b34b-cba71533e844','scannerBId','ed2433cb-bc6e-4b23-aa57-000839292ec4'),false) then raise exception 'exact_source_audit_required';end if;
  if (select count(*) from public.application_events where application_id=(f->>'application')::uuid)<>1 or not exists(select 1 from public.application_events where application_id=(f->>'application')::uuid and from_status is null and to_status='approved' and public_message='SYNTHETIC QA fixture; no real admission.' and guest_message is null and correlation_id=audit.correlation_id) then raise exception 'exact_application_trace_required';end if;
  if (select count(*) from private.outbox where payload->>'application_id'=f->>'application')<>1 or not exists(select 1 from private.outbox where topic='application.status_changed' and status='held' and payload=jsonb_build_object('application_id',f->>'application','eventId',eid,'to','approved','correlation_id',audit.correlation_id,'synthetic',true,'externalDelivery',false)) then raise exception 'exact_held_notification_required';end if;
 end loop;
 if exists(select 1 from private.ticket_passes where id='d0700000-0000-4000-8000-000000000010') or exists(select 1 from private.audit_log where correlation_id='d0700000-0000-4000-8000-000000000011' or action='day07.synthetic_race_pass_seed' and object_id=primary_event.id) then raise exception 'seed_collision_or_retry_reconcile';end if;
 select count(*) into before_outbox from private.outbox;
 insert into private.ticket_passes(id,event_id,participation_id,user_id,guest_name,source,environment,access,reason,sequence_number,token_key_version,view_token_hash,scan_token_hash,valid_until,event_snapshot,issued_by)
 values('d0700000-0000-4000-8000-000000000010',primary_event.id,'d0700000-0000-4000-8000-000000000006','15cbc7a4-92f6-48d8-abb2-ed68f7612271','SYNTHETIC participant','participation','sandbox','GENERAL','Public concurrency fixture; not secure owner issuance',1,'explicit-v2',private.qr_hash(encode(extensions.gen_random_bytes(32),'hex')),private.qr_hash('AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'),primary_event.entry_closes_at,jsonb_build_object('id',primary_event.id,'title',primary_event.title,'timezone',primary_event.timezone,'when',primary_event.starts_at),'15cbc7a4-92f6-48d8-abb2-ed68f7612271');
 insert into private.audit_log(actor,action,object_type,object_id,result,correlation_id,details) values(null,'day07.synthetic_race_pass_seed','event',primary_event.id,'ok','d0700000-0000-4000-8000-000000000011',jsonb_build_object('approvalRef',approval,'rehearsalEvidenceRef',rehearsal,'operatorDbRole',current_user,'fixtureIssuedByAttribution','15cbc7a4-92f6-48d8-abb2-ed68f7612271','actualOwnerIssue',false,'secureEntropyVerified',false,'publicFixture',true,'synthetic',true,'externalDelivery',false,'passId','d0700000-0000-4000-8000-000000000010'));
 if (select count(*) from private.outbox)<>before_outbox then raise exception 'unexpected_notification';end if;
end $seed$;
select jsonb_build_object('passId','d0700000-0000-4000-8000-000000000010','version',1,'generation',1,'publicSyntheticFixture',true,'actualOwnerIssue',false,'secureEntropyVerified',false) as seed_receipt;
commit;
